CREATE TABLE IF NOT EXISTS "screener_history" (
    "observed_on" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "company" TEXT,
    "investment_rank" INTEGER,
    "decision_score" REAL,
    "final_score" REAL,
    "fundamental_score" REAL,
    "technical_score" REAL,
    "rating" TEXT,
    "current_price" REAL,
    "volume" INTEGER,
    "stage" TEXT,
    "market" TEXT NOT NULL DEFAULT 'NSE',
    PRIMARY KEY ("market", "observed_on", "symbol")
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS "screener_history_symbol_idx" ON "screener_history" ("market", "symbol", "observed_on");
